// Quick numeric prototype of the TASK-106 hover controller.
// Mirrors integrateShip's atmosphere branch: drag -> thrust(0) -> gravity -> lift.
const g = 9.8;
const VTOL_LIFT = 1.35 * g;
const KP = 2, KD = 4, HOVER_ALT = 10;

// scout class
const mass = 20, area = 2 * Math.sqrt(mass);

function sim(density, { startAlt = 100, vy0 = 0, ticks = 800, slope = 0 } = {}) {
  const k = (density * area) / mass;
  let y = startAlt, vy = vy0, x = 0, vx = 0;
  let firstIn = -1, worstInBand = 0, inBand = false;
  const band = (alt) => Math.abs(alt - HOVER_ALT) <= 2;
  for (let i = 0; i < ticks; i++) {
    const h = 0.05;
    const alt = y - slope * x;
    const f = Math.max(0, Math.min(1, 1 - alt / 1000)); // boundaryFactor
    const speed = Math.hypot(vx, vy);
    // drag
    vy += -k * f * speed * vy * h;
    // gravity
    vy -= g * h;
    // hover lift (replaces VTOL lift)
    const liftRaw = g + KP * (HOVER_ALT - alt) - KD * vy;
    const lift = Math.max(0, Math.min(VTOL_LIFT, liftRaw));
    vy += lift * h;
