```ts
/**
 * Hover altitude-hold controller (TASK-106) — shared flight model.
 *
 * The PD controller for VTOL hover: while a ship's input carries
 * `hover: 1`, integrateShip replaces the held-key VTOL lift with this
 * deterministic altitude-hold that targets `HOVER_ALT_M` above the local
 * terrain (the `heightAt` seam resampled at every substep, so sloped
 * terrain is tracked).
 *
 * The controller is a NEW branch (gated on input.hover): the held-key
 * 'vtol' path, the VTOL_LIFT / VTOL_HORIZONAL_LIMIT constants and the pad
 * docking logic keep working exactly as before. Lift is bounded by
 * VTOL_LIFT (1.35·g), so a spammed 'hover' tag is harmless — the server
 * re-derives lift from authoritative state (no extra authority for the
 * client).
 *
 * Ordering note: the lift reads the PRE-gravity velocity of the substep and
 * is applied BEFORE the gravity add (the inverse of the legacy VTOL path).
 * Reading the post-gravity velocity would leak a dt·KD·g bias into the
 * equilibrium (a server dt of 0.05 s settles ~1.9 m ABOVE the target while
 * a 60 fps client predictor would settle ~0.3 m above — a systematic
 * prediction offset). Applied pre-gravity, the equilibrium is exactly the
 * target at every dt.
 */

/** Hover altitude (u) above the local terrain. */
export const HOVER_ALT_M = 10;
/** Proportional gain (1/s) on the altitude error. */
export const HOVER_KP = 2;
/** Derivative gain (1/s) on the vertical velocity. */
export const HOVER_KD = 4;

/**
 * The hover lift for one substep (u/s²):
 * lift = clamp(GRAVITY + KP·(target − alt) − KD·vel.y, 0, VTOL_LIFT)
 *
 * Pure: same (alt, velY, gravity, vtolLift) → same lift. GRAVITY is
 * cancelled exactly at the target with zero vertical velocity, so the
 * target is the rest point.
 */
export function hoverLift(alt: number, velY: number, gravity: number, vtolLift: number): number {
  const lift = gravity + HOVER_KP * (HOVER_ALT_M - alt) - HOVER_KD * velY;
  return lift < 0 ? 0 : lift > vtolLift ? vtolLift : lift;
}
```

